const fs = require('fs');
const path = require('path');

const projectRoot = path.resolve(__dirname, '..');

const katexCssPath = path.join(
    projectRoot,
    'node_modules/katex/dist/katex.min.css'
);

const outputPath = path.join(
    projectRoot,
    'src/constants/katexCss.js'
);

if (!fs.existsSync(katexCssPath)) {
    console.error('❌ KaTeX CSS not found. Install katex first.');
    process.exit(1);
}

const css = fs.readFileSync(katexCssPath, 'utf8');

const output = `// Generated automatically from KaTeX.
// Do not edit this file manually.

module.exports = ${JSON.stringify(css)};
`;

fs.mkdirSync(path.dirname(outputPath), {
    recursive: true,
});

fs.writeFileSync(outputPath, output, 'utf8');

console.log('✅ KaTeX CSS generated successfully!');
console.log(`📁 Output: ${outputPath}`);